T0 = 1700000000000; T0 -= T0 % 14400000
def mk(adim, after, limit):
    s = T0 if after is None else int(after); s -= s % adim
    return [[str(s - k*adim), "100", "101", "99", "100", "1000", "1000", "100000", "1"]
            for k in range(limit)]
def yap(bozuk):
    def cek(url, params, zaman_asimi=20):
        p = dict(params or {})
        if "candles" in url:
            adim = 14400000 if str(p.get("bar", "")).upper().startswith("4H") else 900000
            return {"code": "0", "data": mk(adim, p.get("after"), int(p.get("limit", 100)))}
        if "open-interest-history" in url:
            # bozuk=True -> 3 kolon (x[3] YOK); bozuk=False -> 4 kolon (saglam)
            r = [[str(T0-k*900000), str(1000+k), "1", "3e7"] for k in range(100)]
            return {"code": "0", "data": [x[:3] for x in r] if bozuk else r}
        if "taker-volume" in url:
            return {"code": "0", "data": [[str(T0-k*900000), "500", str(500+k % 7)]
                                          for k in range(100)]}
        return {"code": "0", "data": [{"fundingRate": "0.0001"}]}
    return lambda u, p, z=20: m.okx_uyumlu_getir(u, p, z, cek=cek)

